// Public "Categories" page (pre-rendered at /categories): every industry and job title in Doott,
// for India, the USA and every other country with category data. Names only; each link opens that
// exact search in the app (which needs an account).
// Data: categories.json (India / USA) and worldCategories.json (other countries), both generated by
// the count job (src/counts/explorerCards.js, src/counts/worldCategories.js).
import { useState, useMemo } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { Search } from "lucide-react";
import { Nav, Footer } from "./LandingPage";
import { CATEGORIES_DATA, GLOBAL_COUNTRIES, TOTAL_CATEGORIES, CATEGORY_COUNTRIES } from "../categoryStats";
import { PEOPLE_ROLE_GROUPS, COMPANY_INDUSTRY_GROUPS } from "../categoryGroups";
import { flag } from "../countries";

const fmt = (n) => n.toLocaleString("en-US");

const REGIONS = [
  { key: "india", label: "India" },
  { key: "usa", label: "USA" },
  { key: "global", label: "Global" },
];
const MODES = [
  { key: "company", label: "Industries", one: "industry", many: "industries" },
  { key: "people", label: "Job titles", one: "job title", many: "job titles" },
];

/** The cards for a region / country and kind. */
function cardsFor(region, code, mode) {
  if (region !== "global") return CATEGORIES_DATA[region][mode];
  return GLOBAL_COUNTRIES.find((c) => c.code === code)?.[mode] || [];
}

/** The app search a card opens. */
function hrefFor(region, code, mode, name) {
  const enc = encodeURIComponent(name);
  const where = region === "global" ? `country=${code}` : `f_country=${region}`;
  return mode === "people" ? `/app/people?f_job_title_eq=${enc}&${where}` : `/app/companies?f_industry_eq=${enc}&${where}`;
}

const pill = (active) =>
  `px-4 py-2 font-mono text-[11px] uppercase tracking-[0.15em] transition border disabled:opacity-40 disabled:cursor-not-allowed ${
    active
      ? "border-foreground bg-foreground text-background font-semibold"
      : "border-border bg-background/50 text-muted-foreground hover:text-foreground"
  }`;

/** Where ?country=CODE points: { region, code } (India / USA by their tabs, others under Global). */
export function placeFromCode(raw) {
  const c = String(raw || "").toUpperCase();
  if (c === "IN") return { region: "india", code: "" };
  if (c === "US") return { region: "usa", code: "" };
  if (GLOBAL_COUNTRIES.some((g) => g.code === c)) return { region: "global", code: c };
  return null;
}

export default function PublicCategoriesPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const start = placeFromCode(searchParams.get("country")) || { region: "india", code: "" };
  const [region, setRegion] = useState(start.region);
  const [code, setCode] = useState(start.code || GLOBAL_COUNTRIES[0]?.code || "");
  const [mode, setMode] = useState(() => (cardsFor(start.region, start.code || GLOBAL_COUNTRIES[0]?.code, "company").length ? "company" : "people"));
  const [group, setGroup] = useState("all");
  const [query, setQuery] = useState("");

  const all = cardsFor(region, code, mode);
  // Groups only make sense for the long India / USA lists.
  const groups = region === "global" ? [] : mode === "people" ? PEOPLE_ROLE_GROUPS : COMPANY_INDUSTRY_GROUPS;
  const M = MODES.find((m) => m.key === mode);

  const list = useMemo(() => {
    let out = all;
    const g = groups.find((x) => x.key === group);
    if (g?.keywords) out = out.filter((c) => g.keywords.some((kw) => c.name.toLowerCase().includes(kw)));
    const q = query.trim().toLowerCase();
    if (q) out = out.filter((c) => c.name.toLowerCase().includes(q));
    return out;
  }, [all, groups, group, query]);

  // Switching to a place without cards of this kind (most countries have no job-title cards) shows the other kind.
  const pick = (nextRegion, nextCode = code) => {
    setRegion(nextRegion);
    setCode(nextCode);
    setGroup("all");
    if (!cardsFor(nextRegion, nextCode, mode).length) setMode(mode === "people" ? "company" : "people");
    // Keep the choice in the URL so it can be shared (?country=DE).
    const urlCode = nextRegion === "india" ? "IN" : nextRegion === "usa" ? "US" : nextCode;
    setSearchParams({ country: urlCode }, { replace: true });
  };

  const placeName = region === "global" ? GLOBAL_COUNTRIES.find((c) => c.code === code)?.name : REGIONS.find((r) => r.key === region).label;

  return (
    <main className="relative z-[2] min-h-screen bg-background text-foreground">
      <Nav />

      <section className="border-b border-border" aria-label="Doott categories">
        <div className="mx-auto max-w-6xl px-6 pt-20 pb-12 md:pt-24">
          <p className="eyebrow mb-4 opacity-60">◆ {fmt(TOTAL_CATEGORIES)} industries &amp; job titles · {CATEGORY_COUNTRIES} countries</p>
          <div className="flex flex-col md:flex-row md:items-end md:justify-between gap-6">
            <div>
              <h1 className="display text-4xl md:text-6xl max-w-3xl">Browse every category &amp; decision-maker role.</h1>
              <p className="text-muted-foreground mt-5 max-w-2xl text-base leading-relaxed">
                Every industry and job title in Doott, for India, the USA and {GLOBAL_COUNTRIES.length} more countries.
                Open one to see its companies or people.
              </p>
            </div>
            <Link
              to="/app/categories"
              className="inline-flex h-11 items-center gap-2 border border-primary bg-primary px-5 font-mono text-[11px] uppercase tracking-[0.18em] text-primary-foreground transition hover:opacity-90 self-start md:self-auto"
            >
              Open category explorer →
            </Link>
          </div>
        </div>
      </section>

      <section className="border-b border-border bg-secondary/10" aria-label={`${placeName} ${M.many}`}>
        <div className="mx-auto max-w-6xl px-6 py-12">
          {/* Region, country, kind and search */}
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 mb-5">
            <div className="flex flex-wrap items-center gap-2">
              <div role="tablist" aria-label="Region" className="flex flex-wrap gap-2">
                {REGIONS.map((r) => (
                  <button key={r.key} role="tab" aria-selected={region === r.key} onClick={() => pick(r.key)} className={pill(region === r.key)}>
                    {r.label}
                  </button>
                ))}
              </div>
              {region === "global" && (
                <select
                  value={code}
                  onChange={(e) => pick("global", e.target.value)}
                  aria-label="Country"
                  className="h-[38px] max-w-[190px] border border-border bg-background px-2 font-mono text-[11px] uppercase tracking-[0.1em] text-foreground focus:outline-none focus:border-foreground"
                >
                  {GLOBAL_COUNTRIES.map((c) => (
                    <option key={c.code} value={c.code}>{flag(c.code)} {c.name} ({c.company.length + c.people.length})</option>
                  ))}
                </select>
              )}
              <span className="mx-1 h-6 w-px bg-border" aria-hidden="true" />
              {MODES.map((m) => {
                const n = cardsFor(region, code, m.key).length;
                return (
                  <button key={m.key} onClick={() => { setMode(m.key); setGroup("all"); }} disabled={!n} className={pill(mode === m.key)} aria-pressed={mode === m.key}>
                    {m.label} <span className="opacity-60">({n})</span>
                  </button>
                );
              })}
            </div>
            <div className="relative w-full lg:w-[280px]">
              <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
              <input
                type="search"
                placeholder={`Search ${M.many}…`}
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                aria-label={`Search ${M.many}`}
                className="w-full pl-9 pr-4 py-2 border border-border bg-background text-xs text-foreground placeholder:text-muted-foreground/60 focus:outline-none focus:border-foreground font-mono"
              />
            </div>
          </div>

          {groups.length > 0 && (
            <div className="flex flex-wrap gap-2 mb-6 pb-6 border-b border-border">
              {groups.map((g) => (
                <button
                  key={g.key}
                  onClick={() => setGroup(g.key)}
                  aria-pressed={group === g.key}
                  className={`px-3 py-1 border font-mono text-[10px] uppercase tracking-[0.12em] transition-colors ${
                    group === g.key ? "border-foreground text-foreground bg-secondary" : "border-border text-muted-foreground hover:text-foreground"
                  }`}
                >
                  {g.label}
                </button>
              ))}
            </div>
          )}

          <h2 className="font-mono text-[10px] uppercase tracking-[0.15em] text-muted-foreground mb-3">
            {placeName} · {fmt(list.length)} of {fmt(all.length)} {all.length === 1 ? M.one : M.many}
          </h2>
          <div className="border border-border bg-background">
            {list.length === 0 ? (
              <p className="p-8 text-sm text-muted-foreground">Nothing matches “{query}”. Try a shorter word.</p>
            ) : (
              // Styles live on the list (child selectors) so each of the hundreds of links stays small in the pre-rendered HTML.
              <ul className="grid grid-cols-1 gap-px bg-border sm:grid-cols-2 lg:grid-cols-3 [&>li]:bg-background [&_a]:flex [&_a]:items-center [&_a]:justify-between [&_a]:gap-3 [&_a]:px-4 [&_a]:py-3 [&_a]:text-sm [&_a:hover]:bg-secondary/40 [&_a:hover>span:first-child]:text-primary [&_a>span:first-child]:min-w-0 [&_a>span:first-child]:truncate">
                {list.map((c) => (
                  <li key={c.name}>
                    <Link to={hrefFor(region, code, mode, c.name)}><span>{c.name}</span></Link>
                  </li>
                ))}
              </ul>
            )}
          </div>
          <p className="mt-3 text-xs text-muted-foreground">
            Opening a category needs a Doott account. <Link to="/pricing" className="text-primary underline underline-offset-4">Get lifetime access</Link>.
          </p>
        </div>
      </section>

      <Footer />
    </main>
  );
}
